        decision_type,
        COUNT(*) AS cnt
      FROM decision_logs
      WHERE created_at >= date('now','-7 days')
      GROUP BY DATE(created_at), decision_type
      ORDER BY day, cnt DESC
    `).all();
    console.log('\n=== Q7: Decision log by type ===');
    console.log(JSON.stringify(q7, null, 2));

    // Q8: Error / failure rates
    const q8 = db.prepare(`
      SELECT 
