const dbPath = '/c/Users/phila/.muonroi-cli/muonroi.db';
async function query() {
  let db;
  try {
    const mod = await import('better-sqlite3');
    db = new mod.default(dbPath);
  } catch(e1) {
    console.error('better-sqlite3 not available:', e1.message);
    // fallback: try sql.js (WASM) or native
    try {
      const sqlite = await import('sql.js');
      const SQL = await sqlite.default;
      const buf = require('fs').readFileSync(dbPath);
      const db2 = new SQL.Database(buf);
      db = { prepare: (s) => ({ all: () => { throw new Error('sql.js no bind'); } }) };
    } catch(e2) {
      console.error('sql.js also not available:', e2.message);
      process.exit(1);
    }
  }
