  const db = new Database(DB_PATH);
  console.log("DB opened:", DB_PATH);

  // Last 7 days: Oct 2–8 2026
  const rows = db
    .prepare(
      `SELECT created_at, event_type, event_subtype, input_tokens,
              json_extract(metadata_json,'$.bySegment') AS seg
       FROM interaction_logs
       WHERE created_at >= '2026-10-02' AND created_at < '2026-10-09'
       ORDER BY created_at`
    )
    .all();

  console.log(`\nRows in last 7 days: ${rows.length}\n`);

  // Aggregate by event_type
  const byType: Record<string, {count: number; tokens: number}> = {};
  for (const r of rows) {
    const k = r.event_type;
    if (!byType[k]) byType[k] = { count: 0, tokens: 0 };
    byType[k].count++;
    byType[k].tokens += r.input_tokens || 0;
  }
  console.log("By event_type:");
  for (const [k, v] of Object.entries(byType).sort((a,b) => b[1].tokens - a[1].tokens)) {
    console.log(`  ${k.padEnd(24)} calls=${String(v.count).padStart(5)} est_tok=${v.tokens.toLocaleString()}`);
  }

  // call_accounting breakdown
  const ca = rows.filter(r => r.event_type === "call_accounting");
  if (ca.length) {
    console.log("\ncall_accounting segment split (top 10 by tokens):");
    ca.sort((a,b) => (b.input_tokens||0) - (a.input_tokens||0));
    for (const r of ca.slice(0, 10)) {
      const seg = JSON.parse(r.seg || "{}");
      console.log(`  ${r.event_subtype?.padEnd(20)} est=${String(r.input_tokens).padStart(7)}  sys=${seg.system||0}  hist=${seg.history||0}  tool=${seg.toolResults||0}`);
    }
  }

  db.close();
} catch (e) {
  console.error("DB error:", (e as Error).message);

  // ── 2) Fallback: JSONL ────────────────────────────────────────────────────
  console.log("\nFalling back to JSONL cost-log...");
  const usageDir = join(HOME, ".muonroi-cli", "usage");
  const files = readdirSync(usageDir)
    .filter(f => f.startsWith("cost-log-") && f.endsWith(".jsonl"))
    .sort().reverse();
  console.log("cost-log files (newest first):", files.slice(0, 5));

  let totalTokens = 0;
  const byType: Record<string, number> = {};
  for (const f of files) {
    const lines = readFileSync(join(usageDir, f), "utf8").split("\n").filter(Boolean);
    for (const line of lines) {
      try {
        const j = JSON.parse(line);
        const ts = j.ts || j.created_at || "";
        if (ts >= "2026-10-02" && ts < "2026-10-09") {
          const t = j.input_tokens || j.tokens || 0;
          totalTokens += t;
          const k = j.event_type || j.type || "unknown";
          byType[k] = (byType[k] || 0) + t;
        }
      } catch {}
    }
  }
  console.log(`\nTotal est tokens (JSONL fallback): ${totalTokens.toLocaleString()}`);
  console.log("By type:", byType);
}
